//! The material atlas as a GPU texture, sampler and bind group.
//!
//! # Sampling policy
//!
//! The atlas is a 256×256 `Rgba8UnormSrgb` texture with the five per-tile mip
//! levels generated by [`crate::atlas::AtlasBuilder`]. The sampler is:
//!
//! - **magnification: nearest** — voxel faces are 16×16 texels; filtering them
//!   up would blur the intended pixel art;
//! - **minification and mip selection: linear** — the five-level chain reduces
//!   shimmer in the distance;
//! - **address mode: clamp to edge** — the shader keeps UVs inside a tile, and
//!   clamping prevents a bad UV from wrapping into a neighbouring material.
//!
//! The atlas occupies bind group 1 (binding 0 = texture, binding 1 = sampler).
//! The camera uniform is bind group 0.

use wgpu::{
    AddressMode, BindGroup, BindGroupDescriptor, BindGroupEntry, BindGroupLayout,
    BindGroupLayoutDescriptor, BindGroupLayoutEntry, BindingType, Device, Extent3d, FilterMode,
    MipmapFilterMode, Origin3d, Queue, Sampler, SamplerBindingType, SamplerDescriptor,
    ShaderStages, TexelCopyBufferLayout, TexelCopyTextureInfo, Texture, TextureAspect,
    TextureDescriptor, TextureDimension, TextureFormat, TextureSampleType, TextureUsages,
    TextureView, TextureViewDescriptor, TextureViewDimension,
};

use crate::atlas::{ATLAS_SIZE, Atlas, MAX_MIP};

/// Bind-group index used by the atlas.
pub const ATLAS_BIND_GROUP: u32 = 1;

/// The uploaded atlas and its sampling resources.
pub struct AtlasTexture {
    /// The five-level atlas texture.
    pub texture: Texture,
    /// View over every mip level.
    pub view: TextureView,
    /// Nearest-magnification, linear-minification sampler.
    pub sampler: Sampler,
    /// Layout for [`Self::bind_group`].
    pub layout: BindGroupLayout,
    /// Bind group 1: texture at binding 0, sampler at binding 1.
    pub bind_group: BindGroup,
}

impl AtlasTexture {
    /// Uploads every mip level of `atlas` and creates its sampler/bind group.
    pub fn new(device: &Device, queue: &Queue, atlas: &Atlas) -> Self {
        debug_assert_eq!(atlas.mip_count(), MAX_MIP + 1);

        let texture = device.create_texture(&TextureDescriptor {
            label: Some("material atlas"),
            size: Extent3d {
                width: ATLAS_SIZE,
                height: ATLAS_SIZE,
                depth_or_array_layers: 1,
            },
            mip_level_count: atlas.mip_count(),
            sample_count: 1,
            dimension: TextureDimension::D2,
            format: TextureFormat::Rgba8UnormSrgb,
            usage: TextureUsages::TEXTURE_BINDING | TextureUsages::COPY_DST,
            view_formats: &[],
        });

        for (level, mip) in atlas.levels().iter().enumerate() {
            queue.write_texture(
                TexelCopyTextureInfo {
                    texture: &texture,
                    mip_level: level as u32,
                    origin: Origin3d::ZERO,
                    aspect: TextureAspect::All,
                },
                mip.pixels(),
                TexelCopyBufferLayout {
                    offset: 0,
                    bytes_per_row: Some(mip.width() * 4),
                    rows_per_image: Some(mip.height()),
                },
                Extent3d {
                    width: mip.width(),
                    height: mip.height(),
                    depth_or_array_layers: 1,
                },
            );
        }

        let sampler = device.create_sampler(&SamplerDescriptor {
            label: Some("material atlas sampler"),
            address_mode_u: AddressMode::ClampToEdge,
            address_mode_v: AddressMode::ClampToEdge,
            address_mode_w: AddressMode::ClampToEdge,
            mag_filter: FilterMode::Nearest,
            min_filter: FilterMode::Linear,
            mipmap_filter: MipmapFilterMode::Linear,
            lod_min_clamp: 0.0,
            lod_max_clamp: MAX_MIP as f32,
            compare: None,
            anisotropy_clamp: 1,
            border_color: None,
        });

        let layout = device.create_bind_group_layout(&BindGroupLayoutDescriptor {
            label: Some("material atlas"),
            entries: &[
                BindGroupLayoutEntry {
                    binding: 0,
                    visibility: ShaderStages::FRAGMENT,
                    ty: BindingType::Texture {
                        sample_type: TextureSampleType::Float { filterable: true },
                        view_dimension: TextureViewDimension::D2,
                        multisampled: false,
                    },
                    count: None,
                },
                BindGroupLayoutEntry {
                    binding: 1,
                    visibility: ShaderStages::FRAGMENT,
                    ty: BindingType::Sampler(SamplerBindingType::Filtering),
                    count: None,
                },
            ],
        });

        let view = texture.create_view(&TextureViewDescriptor::default());
        let bind_group = device.create_bind_group(&BindGroupDescriptor {
            label: Some("material atlas"),
            layout: &layout,
            entries: &[
                BindGroupEntry {
                    binding: 0,
                    resource: wgpu::BindingResource::TextureView(&view),
                },
                BindGroupEntry {
                    binding: 1,
                    resource: wgpu::BindingResource::Sampler(&sampler),
                },
            ],
        });

        Self {
            texture,
            view,
            sampler,
            layout,
            bind_group,
        }
    }
}
